/* Visual experience v3. Local-only, no network writes. Survey v2 remains intact. */
'use strict';
const visualPositions={me:[510,605],'creative-base':[205,460],'business-base':[510,460],'tech-base':[815,460],content:[125,300],design:[285,300],event:[430,300],research:[590,300],data:[735,300],web:[895,300],story:[125,120],visual:[285,120],marketing:[510,120],analyst:[735,120],product:[895,120]};
const mapGeometry={width:1020,height:670};
let mapBranch='all';
const beforeVisualShell=shell;
shell=function(body){return beforeVisualShell(body).replace(/<a class="brand" href="#home">[\s\S]*?<\/a>/,'<a class="brand" href="#home" aria-label="Higher หน้าหลัก"><img class="brand-image" src="data:image/png;base64," alt="โลโก้ Higher" width="812" height="306"></a>').replace('a little closer to your future.','ค้นพบทางที่เป็นคุณ ทีละก้าว')};
function nodePoint(id){const p=visualPositions[id];return {x:p[0],y:p[1]}}
function branchShown(n){return mapBranch==='all'||n.id==='me'||n.branch===mapBranch}
function visualEdge(a,b){const p=nodePoint(a),q=nodePoint(b);return `M${p.x} ${p.y-43} C${p.x} ${(p.y+q.y)/2},${q.x} ${(p.y+q.y)/2},${q.x} ${q.y+43}`}
function visualStatus(n){const status=nodeState(n);if(status==='current')return 'จุดเริ่มต้นของคุณ';if(status==='done')return 'มีประสบการณ์งานแล้ว';if(n.job){const j=jobs().find(j=>j.id===n.job);return j?`${j.pay.toLocaleString()} บาท / ${j.unit} · ตัวอย่าง`:'โอกาสทดลองงาน'}if(n.needs)return status==='ready'?'มีหลักฐานเริ่มต้นแล้ว':'เพิ่มหลักฐานเพื่อวางก้าวถัดไป';return 'แตะเพื่อดูงานและทักษะ'}
tree=function(){return `<div class="map-space" style="width:${mapGeometry.width*zoom}px;height:${mapGeometry.height*zoom}px"><div class="map-stage" style="transform:scale(${zoom})"><svg class="map-lines" viewBox="0 0 1020 670" aria-hidden="true">${edges.map(([a,b])=>{const p=nodes.find(n=>n.id===a),q=nodes.find(n=>n.id===b),state=nodeState(q);return `<path data-from="${a}" data-to="${b}" d="${visualEdge(a,b)}" class="path ${state==='done'?'explored':state==='ready'?'ready':''} ${selected===a||selected===b?'is-highlight':''}" style="opacity:${branchShown(p)&&branchShown(q)?1:.13}"/>`}).join('')}</svg><span class="branch-label" style="left:105px">${I('pen')}สื่อและความคิดสร้างสรรค์</span><span class="branch-label business" style="left:439px">${I('people')}ธุรกิจและผู้คน</span><span class="branch-label tech" style="left:758px">${I('code')}ดิจิทัลและข้อมูล</span>${nodes.map(n=>{const p=nodePoint(n.id),state=nodeState(n);return `<button class="node ${state} ${selected===n.id?'selected':''}" style="left:${p.x}px;top:${p.y}px;opacity:${branchShown(n)?1:.23}" data-node="${n.id}" aria-pressed="${selected===n.id}" aria-label="${n.title} ${visualStatus(n)}"><span class="node-top"><span class="node-icon">${I(state==='done'?'check':n.icon)}</span><b>${n.title}</b></span><small>${visualStatus(n)}</small>${state==='done'?'<span class="node-badge">ผ่านงานแล้ว</span>':n.job?'<span class="node-badge">งานทดลอง</span>':''}</button>`}).join('')}</div></div>`};
function mapControls(){return `<div class="map-controls"><button data-map-zoom="out" aria-label="ย่อแผนผัง">−</button><span>${Math.round(zoom*100)}%</span><button data-map-zoom="in" aria-label="ขยายแผนผัง">+</button><button data-map-zoom="fit" aria-label="ดูแผนผังทั้งหมด">${I('target')}</button></div>`}
function branchSwitch(){return `<div class="branch-toggle" role="group" aria-label="เลือกกลุ่มเส้นทาง">${[['all','ทุกกิ่ง'],['creative','สร้างสรรค์'],['business','ธุรกิจ'],['tech','ดิจิทัล']].map(([id,label])=>`<button data-map-branch="${id}" class="${mapBranch===id?'active':''}" aria-pressed="${mapBranch===id}">${label}</button>`).join('')}</div>`}
function mapFooter(){return `<div class="map-bottom"><span>${I('heart')} ทุกกิ่งเปิดให้สำรวจ ไม่ต้องเลือกแค่เส้นทางเดียว</span><span class="map-hint">${I('settings')} ลากพื้นที่ว่างเพื่อเลื่อนแผนที่</span></div>`}
function nextStepPanel(){const j=rankedJobs()[0];return `<section class="panel"><div class="panel-top"><div><h2>หนึ่งก้าวที่คุณเริ่มได้</h2><p>เลือกงานเล็ก ๆ เพื่อรู้จักตัวเองมากขึ้น</p></div>${I('briefcase')}</div><div class="mini-list">${rankedJobs().slice(0,2).map(j=>`<div class="mini-row"><div class="logo-tile">${esc(j.initial)}</div><div><b>${esc(j.title)}</b><p>${esc(j.company)} · ${esc(j.place)}</p></div><div class="right"><strong>฿${j.pay}</strong><p>ต่อ${esc(j.unit)} · จำลอง</p></div><button class="icon-button" data-job="${j.id}" aria-label="ดู ${esc(j.title)}">${I('arrow')}</button></div>`).join('')}</div></section>`}
roadmap=function(){const s=assessmentStore(),hasCompleted=completed().length>0;return `<div class="roadmap-v3">${head('YOUR JOURNEY, YOUR WAY','เส้นทางที่เป็นคุณ เริ่มได้หลายทาง','มองเห็นสิ่งที่ลองได้วันนี้ และโอกาสที่ค่อย ๆ เติบโตจากประสบการณ์',btn(s.common.complete?'ดูผลสำรวจของฉัน':'เริ่มรู้จักตัวเอง',`data-go="assessment"`,'soft','spark'))}${stats()}<div class="map-layout"><section class="panel map-main"><div class="panel-top"><div><h2>แผนที่โอกาสของ ${esc(db.profile.name)}</h2><p>แตะแต่ละกิ่ง เพื่อดูงาน ทักษะ และก้าวถัดไป</p></div><div class="segmented"><button class="${mapView==='tree'?'active':''}" data-view="tree">แผนผัง</button><button class="${mapView==='history'?'active':''}" data-view="history">ประสบการณ์</button></div></div>${mapView==='tree'?`<div class="map-message">${I('spark')}<span>${s.common.complete?'ความสนใจช่วยเลือกสิ่งที่อยากลอง ส่วนหลักฐานจากโจทย์และงานช่วยวางก้าวถัดไป':'ยังไม่รู้ว่าตัวเองชอบอะไร? เริ่มสำรวจทุกกิ่งได้เลย หรือทำแบบสำรวจเพื่อรู้จักตัวเองเพิ่ม'}</span></div><div class="map-toolbar">${branchSwitch()}${mapControls()}</div><div class="map-viewport" id="map-viewport" tabindex="0" role="region" aria-label="แผนผังเส้นทาง ใช้แป้นลูกศรเลื่อน หรือแตะโหนดเพื่อดูรายละเอียด">${tree()}</div>${mapFooter()}`:`<div style="padding:27px">${historyContent()}</div>`}</section><aside id="node-detail">${detail()}</aside></div><div class="below-grid">${nextStepPanel()}<section class="panel"><div class="panel-top"><div><h2>เส้นทางเปลี่ยนได้ เมื่อคุณได้ลอง</h2><p>ทั้งประสบการณ์และความรู้สึกมีความหมาย</p></div>${I('heart')}</div><div class="update-block"><div class="round-icon">${I(hasCompleted?'check':'book')}</div><div><b>${hasCompleted?'คุณมีเรื่องราวจากการทำงานแล้ว':'ยังไม่มีประสบการณ์ก็เริ่มได้'}</b><p>${hasCompleted?'ผลงานและความคิดเห็นถูกบันทึกเป็นหลักฐาน พร้อมเปิดให้คุณลองกิ่งเดิมหรือเปลี่ยนไปสำรวจกิ่งอื่น':'เลือกงานที่มีโจทย์และพี่เลี้ยงชัดเจน แล้วค่อยค้นพบว่าคุณชอบอะไร ทำอะไรได้ และอยากฝึกอะไรเพิ่ม'}</p>${btn('ดูประสบการณ์ของฉัน',`data-go="work"`,'small')}</div></div></section></div><p class="key-note">งานและเส้นทางเป็นตัวอย่างเพื่อสาธิต ไม่รับประกันงาน รายได้ หรืออาชีพในอนาคต</p></div>`};
home=function(){const s=assessmentStore();return head('A LITTLE CLOSER, EVERY DAY',`สวัสดี ${esc(db.profile.name)}`,'ไม่ต้องรู้คำตอบทั้งหมดในวันนี้ เริ่มจากสิ่งเล็ก ๆ ที่อยากลอง',btn('โปรไฟล์ของฉัน',`data-go="profile"`,'','user'))+`<section class="home-welcome"><div><span class="welcome-tag">${I('spark')}YOUR NEXT CHAPTER</span><h2>สิ่งที่เรียนวันนี้<br><em>พาคุณไปลองอะไรได้บ้าง?</em></h2><p>ค้นหางานที่เชื่อมกับสิ่งที่เรียน ลงมือทำจริงในโจทย์ตัวอย่าง และใช้ประสบการณ์ช่วยเลือกเส้นทางที่เหมาะกับตัวเอง</p><div class="home-actions">${btn('เปิดแผนที่เส้นทาง',`data-go="roadmap"`,'primary','map')}${btn(s.common.complete?'ดูผลสำรวจของฉัน':'เริ่มสำรวจตัวเอง',`data-go="assessment"`,'','arrow')}</div></div><div class="mini-journey" aria-label="จากสิ่งที่เรียน ไปสู่งานที่ลอง และเส้นทางของคุณ"><button class="journey-stop" data-go="assessment">${I('book')}รู้จักตัวเอง</button>${I('arrow')}<button class="journey-stop" data-go="jobs">${I('briefcase')}ลองงานจริง</button>${I('arrow')}<button class="journey-stop" data-go="roadmap">${I('map')}เห็นทางไปต่อ</button></div></section>${stats()}<div class="section-head"><div><h2>โอกาสเล็ก ๆ ที่น่าลอง</h2><p>เลือกดูสิ่งที่สนใจ โดยยังไม่ต้องตัดสินอนาคต</p></div>${btn('ดูงานทั้งหมด',`data-go="jobs"`,'small','arrow')}</div><div class="job-grid">${rankedJobs().slice(0,3).map(jobCard).join('')}</div><div class="home-intro-note"><span>พื้นที่ทดลองของ Higher · ข้อมูลอยู่เฉพาะเบราว์เซอร์นี้<br>งาน ค่าตอบแทน และการประเมินเป็นตัวอย่างจำลอง</span><a href="#assessment">ทำความเข้าใจแบบสำรวจ →</a></div>`};
const beforeVisualRender=render;
let lastMapScroll=null,lastRoute=null;
function syncCanvas(center=false){const viewport=$('#map-viewport'),stage=$('.map-stage'),space=$('.map-space');if(!viewport||!stage||!space)return;stage.style.transform=`scale(${zoom})`;stage.style.scale='1';space.style.width=mapGeometry.width*zoom+'px';space.style.height=mapGeometry.height*zoom+'px';const label=document.querySelector('.map-controls span');if(label)label.textContent=Math.round(zoom*100)+'%';if(center){viewport.scrollLeft=Math.max(0,(mapGeometry.width*zoom-viewport.clientWidth)/2);viewport.scrollTop=Math.max(0,(mapGeometry.height*zoom-viewport.clientHeight)/2)}else if(lastMapScroll){viewport.scrollLeft=lastMapScroll.left;viewport.scrollTop=lastMapScroll.top}}
render=function(){const vp=$('#map-viewport');if(vp&&lastRoute==='roadmap')lastMapScroll={left:vp.scrollLeft,top:vp.scrollTop};beforeVisualRender();if(page==='roadmap'&&mapView==='tree')requestAnimationFrame(()=>syncCanvas(!lastMapScroll||lastRoute!=='roadmap'));lastRoute=page};
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.mapZoom){const vp=$('#map-viewport');if(!vp)return;const old=zoom,cx=(vp.scrollLeft+vp.clientWidth/2)/old,cy=(vp.scrollTop+vp.clientHeight/2)/old;zoom=t.dataset.mapZoom==='fit'?Math.max(.35,Math.min(1,Math.min((vp.clientWidth-24)/mapGeometry.width,(vp.clientHeight-24)/mapGeometry.height))):Math.max(.45,Math.min(1.5,Math.round((zoom+(t.dataset.mapZoom==='in'?.1:-.1))*100)/100));lastMapScroll=null;syncCanvas(false);if(t.dataset.mapZoom==='fit')syncCanvas(true);else{vp.scrollLeft=cx*zoom-vp.clientWidth/2;vp.scrollTop=cy*zoom-vp.clientHeight/2}return}
if(t.dataset.mapBranch){mapBranch=t.dataset.mapBranch;const vp=$('#map-viewport');lastMapScroll=vp?{left:vp.scrollLeft,top:vp.scrollTop}:null;render();return}
if(t.dataset.node){document.querySelectorAll('.map-lines path').forEach(p=>p.classList.toggle('is-highlight',p.dataset.from===selected||p.dataset.to===selected));document.querySelectorAll('.node[data-node]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.node===selected)));return}});
let pan=null;
document.addEventListener('pointerdown',e=>{const vp=e.target.closest?.('#map-viewport');if(!vp||e.target.closest('button')||e.pointerType==='touch'||e.button!==0)return;pan={viewport:vp,x:e.clientX,y:e.clientY,left:vp.scrollLeft,top:vp.scrollTop,id:e.pointerId};vp.classList.add('is-panning');vp.setPointerCapture?.(e.pointerId);e.preventDefault()});
document.addEventListener('pointermove',e=>{if(!pan)return;pan.viewport.scrollLeft=pan.left-(e.clientX-pan.x);pan.viewport.scrollTop=pan.top-(e.clientY-pan.y)});
function stopPan(){if(!pan)return;pan.viewport.classList.remove('is-panning');lastMapScroll={left:pan.viewport.scrollLeft,top:pan.viewport.scrollTop};try{pan.viewport.releasePointerCapture?.(pan.id)}catch{}pan=null}
document.addEventListener('pointerup',stopPan);document.addEventListener('pointercancel',stopPan);
document.addEventListener('keydown',e=>{if(e.target.id!=='map-viewport')return;const distances={ArrowLeft:[-90,0],ArrowRight:[90,0],ArrowUp:[0,-90],ArrowDown:[0,90]};if(distances[e.key]){e.preventDefault();const [x,y]=distances[e.key];e.target.scrollLeft+=x;e.target.scrollTop+=y}});
render();
